insert into public.events (slug, title, short_description, description, category, is_published, is_featured, media)
values
  ('noche-de-flores', 'Noche de Flores', 'Mexican Night', 'A Mexican-inspired night with orange marigolds, red and ivory papel picado and violet light. Choose an original floral, half-face or calavera design at the face-paint station. The DJ moves from Mexican favourites to Spanish-language dance tracks and a marigold disco finale. An Early Bird release is planned.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#ff963b","secondaryColor":"#541738","surface":"dark","channels":["events"]}}'::jsonb),
  ('masquerade-party', 'MASQUERADE', 'Masquerade Party', 'A masked night with velvet, warm gold, a 360-degree video booth and a masked dance floor. Bring a mask and dress for an evening in black and gold.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#d9b76c","secondaryColor":"#251b30","surface":"dark","channels":["events"]}}'::jsonb),
  ('cowboy-night', 'Cowboy Night', 'Western Party', 'A Western gathering with ranch-style décor, a cowboy dress code and a dance floor after sundown. Horse riding is planned as a supervised activity, subject to venue and operator confirmation.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#ffc585","secondaryColor":"#432719","surface":"dark","channels":["events"]}}'::jsonb),
  ('super-party', 'Super Party', 'High-energy dance night', 'A high-energy Planet Infinity party concept with a neon-lit dance floor, DJ sets and short crowd games between sets. The programme and location are in development.', 'Party', false, true, '{"conceptPreview":true,"launchStatus":"draft","visualTheme":{"primaryColor":"#adf773","secondaryColor":"#25164a","surface":"dark","channels":["events"]}}'::jsonb)
